package com.netec.exams.notification.infrastructure.outbox;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="notification_outbox") public class NotificationOutbox { @Id private UUID id; @Column(name="aggregate_id",nullable=false) private UUID aggregateId; @Column(name="notification_type",nullable=false) private String notificationType; @Column(name="sender_upn_snapshot",nullable=false) private String senderUpnSnapshot; @Column(nullable=false) private String recipient; @Column(nullable=false) private String cc; @Column(nullable=false) private String subject; @Column(nullable=false,columnDefinition="text") private String payload; @Column(name="idempotency_key",nullable=false,unique=true) private String idempotencyKey; @Column(nullable=false) private String status; private int attempts; @Column(name="next_attempt_at") private Instant nextAttemptAt; @Column(name="last_error_message") private String lastErrorMessage; @Column(name="created_at") private Instant createdAt; @Column(name="processing_started_at") private Instant processingStartedAt; @Column(name="sent_at") private Instant sentAt; @Version private long version; protected NotificationOutbox(){} public static NotificationOutbox pending(UUID aggregate,String sender,String recipient,String cc,String subject,String payload,String key,Instant now){var x=new NotificationOutbox();x.id=UUID.randomUUID();x.aggregateId=aggregate;x.notificationType="APPROVAL_REQUEST";x.senderUpnSnapshot=sender;x.recipient=recipient;x.cc=cc;x.subject=subject;x.payload=payload;x.idempotencyKey=key;x.status="PENDING";x.nextAttemptAt=now;x.createdAt=now;return x;} public UUID id(){return id;} public String status(){return status;} public String senderUpnSnapshot(){return senderUpnSnapshot;} public String recipient(){return recipient;} public String cc(){return cc;} public String subject(){return subject;} public String payload(){return payload;} public void sent(Instant now){status="SENT";sentAt=now;} public void failed(String message,Instant now){status="FAILED";lastErrorMessage=message==null?"Graph send failed":message.substring(0,Math.min(1000,message.length()));nextAttemptAt=now.plusSeconds(60);attempts++;} }
